import {canonical,checked,decode,readManaged,syncDir,writeExclusive,ensureManagedDirectory} from './universe-files';
type Participant={owner:Owner;rootId:string;expectedGeneration:string;targetGeneration:string;fencingToken:string;planDigest:string};
type LedgerRecord={schemaVersion:1;operationId:string;requestDigest:string;participants:Participant[];receipt:WorkspaceReceipt;state:'preparing'|'prepared'|'commit'|'complete'|'aborted'};
const APP_ID=1465140302;
export class WorkspaceCoordinator implements WorkspaceDecisionLedger {
 readonly id:string;private db:DatabaseSync;private stores=new Map<string,WorkspaceStore>();private recovering=new Set<string>();
 constructor(readonly userData:string){ensureManagedDirectory(userData,'database');const filename=path.join(userData,'database/workspace-coordinator.sqlite'),exists=fs.existsSync(filename);if(!exists)writeExclusive(filename,'');this.db=connect(filename,!exists,APP_ID);if(!exists){this.db.exec(`PRAGMA application_id=${APP_ID};PRAGMA user_version=1;CREATE TABLE coordinator_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),id TEXT NOT NULL);CREATE TABLE coordinator_operations(operationId TEXT PRIMARY KEY,requestDigest TEXT NOT NULL,state TEXT NOT NULL,record TEXT NOT NULL);CREATE TABLE coordinator_bindings(rootId TEXT PRIMARY KEY,ownerKind TEXT NOT NULL,ownerId TEXT NOT NULL,universeId TEXT NOT NULL,basePath TEXT NOT NULL);`);this.db.prepare('INSERT INTO coordinator_identity VALUES(1,?)').run(randomUUID());syncDir(path.dirname(filename));}const identity=this.db.prepare('SELECT id FROM coordinator_identity WHERE singleton=1').get();if(!identity||!isUuid(identity.id))throw new UniverseFailure('RECOVERY_REQUIRED','The coordinator identity is missing.','unknown');this.id=String(identity.id);}
 register(store:WorkspaceStore):void{const m=store.identity();this.db.prepare('INSERT INTO coordinator_bindings VALUES(?,?,?,?,?) ON CONFLICT(rootId) DO UPDATE SET basePath=excluded.basePath').run(m.rootId,m.owner.kind,m.owner.id,m.universeId,store.location);this.stores.set(m.rootId,store);}
 /** Purpose-bound recovery location, before opening either side of an interrupted coordinated activation. */
 locateActivationParticipant(owner:Owner,rootId:string,universeId:string,location:string):void{
  if(!validActivationPath(location))throw new Error('Invalid activation path bytes.');
  const root=fs.realpathSync(location),discovery=decode(readManaged(root,'writingtool.json')) as {kind?:string;id?:string;rootId?:string};
  if(discovery.kind!==owner.kind||discovery.id!==owner.id||discovery.rootId!==rootId)throw new Error('The activation location has a different permanent identity.');
  const prior=this.db.prepare('SELECT * FROM coordinator_bindings WHERE rootId=?').get(rootId);
  if(prior){
   if(prior.ownerKind!==owner.kind||prior.ownerId!==owner.id||prior.universeId!==universeId)throw new Error('The original coordinator binding has a different owner.');
   if(String(prior.basePath)!==root){const original=activationRootAt(String(prior.basePath),{owner,rootId});if(original&&original!==root)throw new Error('The original activation authority is still accessible.');}
  }
  this.db.prepare('INSERT INTO coordinator_bindings VALUES(?,?,?,?,?) ON CONFLICT(rootId) DO UPDATE SET basePath=excluded.basePath').run(rootId,owner.kind,owner.id,universeId,root);
 }
 unregister(store:WorkspaceStore):void{for(const [id,current]of this.stores)if(current===store)this.stores.delete(id);}
 private record(id:string,digest?:string):LedgerRecord{const row=this.db.prepare('SELECT * FROM coordinator_operations WHERE operationId=?').get(id);if(!row||typeof row.record!=='string')throw new UniverseFailure('RECOVERY_REQUIRED','The original coordinated decision is unavailable.','unknown');const value=decode(Buffer.from(row.record));if(!closed(value,['schemaVersion','operationId','requestDigest','participants','receipt','state']))throw new UniverseFailure('RECOVERY_REQUIRED','The coordinator record schema is invalid.','unknown');const r=value as LedgerRecord;if(!validWorkspaceReceipt(r.receipt)||r.receipt.operationId!==id||!Array.isArray(r.participants)||r.participants.length!==2||!r.participants.every(p=>closed(p,['owner','rootId','expectedGeneration','targetGeneration','fencingToken','planDigest'])&&validOwner(p.owner)&&isUuid(p.rootId)&&unsignedInteger(p.expectedGeneration)&&unsignedInteger(p.targetGeneration)&&BigInt(p.targetGeneration)===BigInt(p.expectedGeneration)+1n&&isUuid(p.fencingToken)&&(p.planDigest===''&&(r.state==='preparing'||r.state==='aborted')||/^[a-f0-9]{64}$/.test(p.planDigest)))||new Set(r.participants.map(p=>p.rootId)).size!==r.participants.length||!['preparing','prepared','commit','complete','aborted'].includes(r.state))throw new UniverseFailure('RECOVERY_REQUIRED','The coordinator plan is invalid.','unknown');if(r.schemaVersion!==1||r.operationId!==id||r.requestDigest!==row.requestDigest||r.state!==row.state||digest&&digest!==r.requestDigest)throw new UniverseFailure('OPERATION_CONFLICT','The coordinated operation does not match its original request.','unknown');return r;}
 private save(record:LedgerRecord):void{const bytes=canonical(record);transaction(this.db,()=>{this.db.prepare('INSERT INTO coordinator_operations VALUES(?,?,?,?) ON CONFLICT(operationId) DO UPDATE SET state=excluded.state,record=excluded.record').run(record.operationId,record.requestDigest,record.state,bytes);});}
 decision(id:string,digest:string):'commit'|'abort'{const r=this.record(id,digest);return r.state==='commit'||r.state==='complete'?'commit':'abort';}
 receipt(id:string,digest?:string):WorkspaceReceipt|undefined{if(!this.db.prepare('SELECT operationId FROM coordinator_operations WHERE operationId=?').get(id))return;const r=this.record(id,digest);if(r.state==='commit'||r.state==='complete'){if(r.state!=='complete')this.recover(id);return r.receipt;}if(r.state!=='aborted')this.recover(id);const reconciled=this.record(id,digest);if(digest&&reconciled.state==='aborted')throw new UniverseFailure('OPERATION_CONFLICT','This operation was confirmed not committed by its original coordinator. Retry the retained edits with a new operation ID.','not-committed');return;}
 commit(operationId:string,digest:string,plans:{owner:Owner;plan:WorkspaceCommit}[],receipt:WorkspaceReceipt,request:WorkspaceOperationRequest):WorkspaceReceipt {
  const prior=this.receipt(operationId,digest);if(prior)return prior;
  const resolved=plans.map(p=>{const store=[...this.stores.values()].find(s=>canonical(s.identity().owner)===canonical(p.owner));if(!store)throw new UniverseFailure('RECOVERY_REQUIRED','A required authority is unavailable.','unknown');return{store,plan:p.plan};});
  const ordered=resolved.sort((a,b)=>{const x=a.store.identity().owner,y=b.store.identity().owner;return(x.kind+'/'+x.id).localeCompare(y.kind+'/'+y.id);});
  let record:LedgerRecord={schemaVersion:1,operationId,requestDigest:digest,participants:ordered.map(p=>{const m=p.store.identity();return{owner:m.owner,rootId:m.rootId,expectedGeneration:m.generation,targetGeneration:(BigInt(m.generation)+1n).toString(),fencingToken:m.sessionToken,planDigest:''};}),receipt,state:'preparing'};this.save(record);
  try{const journals=ordered.map(p=>({store:p.store,journal:p.store.prepare(operationId,digest,p.plan,receipt,request,true)}));if(!journals.every(p=>canonical(p.journal.receipt)===canonical(journals[0].journal.receipt)))throw new Error('Participant receipt mismatch');record={...record,state:'prepared',participants:journals.map(p=>({...record.participants.find(x=>x.rootId===p.journal.rootId)!,planDigest:p.journal.planDigest,expectedGeneration:p.journal.expectedGeneration,targetGeneration:p.journal.targetGeneration,fencingToken:p.journal.fencingToken})),receipt:journals[0].journal.receipt};this.save(record);journals.forEach(p=>p.store.publish(p.journal,p.journal.fencingToken!==p.store.identity().sessionToken));record={...record,state:'commit'};this.save(record);journals.forEach(p=>p.store.apply(p.journal,p.journal.fencingToken!==p.store.identity().sessionToken));journals.forEach(p=>p.store.finalize(p.journal));this.save({...record,state:'complete'});return record.receipt;}catch{ordered.forEach(p=>p.store.markBlocked());throw new UniverseFailure('RECOVERY_REQUIRED','The coordinated save requires reconciliation of every original participant.','unknown');}
 }
 recover(id:string):void {
  if(!this.db.prepare('SELECT operationId FROM coordinator_operations WHERE operationId=?').get(id))return;if(this.recovering.has(id))return;this.recovering.add(id);const temporary:{store:WorkspaceStore;db:DatabaseSync;lease:DatabaseSync}[]=[];
  try{let r=this.record(id);if(r.state==='complete'||r.state==='aborted')return;const participants=[...r.participants].sort((a,b)=>(a.owner.kind+'/'+a.owner.id).localeCompare(b.owner.kind+'/'+b.owner.id));
   // Reuse existing authority; absent participants acquire their existing lease, never a competing live store.
   const stores=participants.map(p=>{let store=this.stores.get(p.rootId);if(store){store.identity();return{store,p};}const binding=this.db.prepare('SELECT * FROM coordinator_bindings WHERE rootId=?').get(p.rootId);if(!binding||binding.ownerId!==p.owner.id||binding.ownerKind!==p.owner.kind)throw new Error('Missing participant binding');const root=String(binding.basePath),d=decode(readManaged(root,'writingtool.json')) as {id:string;rootId:string;kind:string};if(d.id!==p.owner.id||d.rootId!==p.rootId||d.kind!==p.owner.kind)throw new Error('Participant identity mismatch');const appId=p.owner.kind==='project'?1465140301:1465140300;const lease=connect(checked(root,'database/lease.sqlite'),false,appId);let db:DatabaseSync|undefined;try{lease.exec('BEGIN EXCLUSIVE');const identity=lease.prepare('SELECT * FROM lease_identity').get();if(identity?.ownerId!==p.owner.id||identity?.rootId!==p.rootId)throw new Error('Participant lease mismatch');db=connect(checked(root,'database/catalog.sqlite'),false,appId);const catalog=db;const health=()=>{if(!lease.isTransaction)throw new Error('Lost participant lease');const current=decode(readManaged(root,'writingtool.json')) as {id:string;rootId:string};if(current.id!==p.owner.id||current.rootId!==p.rootId)throw new Error('Participant root changed');};store=new WorkspaceStore(root,catalog,()=>{health();const m=catalog.prepare('SELECT * FROM unit_meta WHERE singleton=1').get()!;return{owner:p.owner,rootId:p.rootId,universeId:p.owner.kind==='universe'?p.owner.id:String(m.universeId),generation:String(m.generation),sessionToken:String(m.sessionToken)};},health,this);this.register(store);temporary.push({store,db:catalog,lease});return{store,p};}catch(e){db?.close();if(lease.isTransaction)lease.exec('ROLLBACK');lease.close();throw e;}});
   const plans=stores.flatMap(({store,p})=>{
    if(r.state==='preparing'&&!p.planDigest&&store.abortUnprepared(id,p.expectedGeneration))return[];
    const journal=store.readJournal(id);if(journal.scope!=='coordinated'||journal.coordinatorId!==this.id||journal.requestDigest!==r.requestDigest||canonical(journal.receipt)!==canonical(r.receipt)||(p.planDigest&&p.planDigest!==journal.planDigest))throw new Error('Coordinated plan mismatch');return[{store,journal}];
   });
   if(r.state==='commit'){plans.forEach(p=>p.store.publish(p.journal,true));plans.forEach(p=>p.store.apply(p.journal,true));plans.forEach(p=>p.store.finalize(p.journal));r={...r,state:'complete'};}else{plans.forEach(p=>p.store.undo(p.journal));r={...r,state:'aborted',participants:r.participants.map(p=>({...p,planDigest:plans.find(plan=>plan.journal.rootId===p.rootId)?.journal.planDigest??p.planDigest}))};}this.save(r);if(r.state==='aborted')for(const {store,p}of stores)if(!r.participants.find(participant=>participant.rootId===p.rootId)!.planDigest)store.removeAbortedEmptyDirectory(id);
  }catch{try{for(const participant of this.record(id).participants)this.stores.get(participant.rootId)?.markBlocked();}catch{}throw new UniverseFailure('RECOVERY_REQUIRED','The original coordinator or a required participant cannot be reconciled. All evidence was retained.','unknown');}
  finally{for(const t of temporary.reverse()){this.unregister(t.store);t.db.close();if(t.lease.isTransaction)t.lease.exec('ROLLBACK');t.lease.close();}this.recovering.delete(id);}
 }
 /** Empty participant staging is recoverable only under its original durable abort. */
 recoverUnprepared(operationId:string,rootId:string):boolean{
  if(!this.db.prepare('SELECT operationId FROM coordinator_operations WHERE operationId=?').get(operationId))return false;
  let record=this.record(operationId);const participant=record.participants.find(p=>p.rootId===rootId);
  if(!participant||participant.planDigest||!['preparing','aborted'].includes(record.state))return false;
  this.recover(operationId);record=this.record(operationId);return record.state==='aborted';
 }
 assertUnreferenced(universeId:string,removedIds:string[],validatedProjectIds:string[]):void {
  if(!removedIds.length)return;
  for(const binding of this.db.prepare("SELECT * FROM coordinator_bindings WHERE ownerKind='project' AND universeId=? ORDER BY ownerId").all(universeId)){
   const projectId=String(binding.ownerId);if(validatedProjectIds.includes(projectId))continue;let lease:DatabaseSync|undefined,catalog:DatabaseSync|undefined;
   try{const root=String(binding.basePath),d=decode(readManaged(root,'writingtool.json')) as {id:string;rootId:string;kind:string};if(d.kind!=='project'||d.id!==projectId||d.rootId!==binding.rootId)throw new Error('Project binding changed');lease=connect(checked(root,'database/lease.sqlite'),false,1465140301);lease.exec('BEGIN EXCLUSIVE');const identity=lease.prepare('SELECT * FROM lease_identity').get();if(identity?.ownerId!==projectId||identity.rootId!==binding.rootId)throw new Error('Project ownership mismatch');catalog=new DatabaseSync(checked(root,'database/catalog.sqlite'),{readOnly:true});if(catalog.prepare('PRAGMA quick_check').get()?.quick_check!=='ok'||catalog.prepare('PRAGMA user_version').get()?.user_version!==1||catalog.prepare('PRAGMA application_id').get()?.application_id!==1465140301)throw new Error('Unrecognized dependency catalog');const meta=catalog.prepare('SELECT * FROM unit_meta WHERE singleton=1').get();if(meta?.ownerId!==projectId||meta.rootId!==binding.rootId||meta.creationState!=='complete')throw new Error('Project identity mismatch');if(meta.universeId!==universeId)continue;
    const operations=path.join(root,'database/operations');if(fs.existsSync(operations))for(const id of fs.readdirSync(checked(root,'database/operations',true))){if(!isUuid(id))throw new Error('Unknown project operation');const journal=decode(readManaged(root,`database/operations/${id}/journal.json`)) as WorkspaceJournal;if(journal.command!=='workspace.publish'||journal.operationId!==id)throw new Error('Unknown dependency operation');const finalized=fs.existsSync(path.join(root,`database/operations/${id}/finalized.json`)),aborted=fs.existsSync(path.join(root,`database/operations/${id}/aborted.json`));if(finalized===aborted)throw new Error('Unfinished project dependency operation');if(journal.scope==='coordinated'&&this.record(id).state!=='complete'&&this.record(id).state!=='aborted')throw new Error('Unfinished coordinated dependency');}
    const feature=catalog.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='workspace_features'").get();if(!feature)continue;const features=catalog.prepare('SELECT * FROM workspace_features').all();if(features.length!==1||features[0].name!=='workspace-content'||features[0].version!==1)throw new Error('Unsupported dependency feature');
    const dependencyCatalog=catalog;const health=()=>{if(!lease?.isTransaction)throw new Error('Dependency lease lost');};const dependency=new WorkspaceStore(root,dependencyCatalog,()=>({owner:{kind:'project',id:projectId},rootId:String(binding.rootId),universeId,generation:String(meta.generation),sessionToken:String(meta.sessionToken)}),health);const snapshot=dependency.snapshot();const references=snapshot.records.flatMap(r=>r.recordType==='chapter'?[...r.data.characterIds,...r.data.events.map(e=>e.eventId)]:r.recordType==='decision-context'?[r.data.decisionId]:[]);if(references.some(id=>removedIds.includes(id)))throw new UniverseFailure('VALIDATION','A known project still references a record being removed. Open that project and resolve its references first.');
   }catch(e){if(e instanceof UniverseFailure&&e.code==='VALIDATION')throw e;throw new UniverseFailure('RECOVERY_REQUIRED','A known project dependency is unavailable or unfinished. Reopen it before removing shared records.');}
   finally{catalog?.close();if(lease?.isTransaction)lease.exec('ROLLBACK');lease?.close();}
  }
 }
 settingsGate<T>(fn:()=>T):T{this.db.exec('BEGIN IMMEDIATE');try{const result=fn();this.db.exec('COMMIT');return result;}catch(e){if(this.db.isTransaction)this.db.exec('ROLLBACK');throw e;}}
 close():void{this.db.close();}
}
