import type {WorkspaceRecord} from './workspace';
export type Reference={targetId:string;label:string;canRemove:boolean;replace:(record:WorkspaceRecord,id:string|null)=>WorkspaceRecord};
/** All persisted record links; exact calendar-version/image identities have their own closure checks. */
export function recordReferences(record:WorkspaceRecord):Reference[]{const refs:Reference[]=[];const field=(name:string,id:string|null,optional=false)=>{if(id)refs.push({targetId:id,label:name,canRemove:optional,replace:(r,value)=>({...r,data:{...r.data,[name]:value}} as WorkspaceRecord)});};const list=(name:string,ids:string[])=>ids.forEach(id=>refs.push({targetId:id,label:name,canRemove:true,replace:(r,value)=>({...r,data:{...r.data,[name]:(r.data as unknown as Record<string,string[]>)[name].flatMap(v=>v===id?value?[value]:[]:[v])}} as WorkspaceRecord)}));const maker=()=>{if('maker'in record.data&&record.data.maker){const id=record.data.maker.id;refs.push({targetId:id,label:'maker',canRemove:true,replace:(r,value)=>({...r,data:{...r.data,maker:value?{...(r.data as typeof record.data&{maker:{kind:string;id:string}}).maker,id:value}:null}} as WorkspaceRecord)});}};
 switch(record.recordType){case'story':field('volumeId',record.data.volumeId,true);break;case'chapter':field('storyId',record.data.storyId);list('characterIds',record.data.characterIds);record.data.events.forEach(link=>refs.push({targetId:link.eventId,label:'chapter event',canRemove:true,replace:(r,value)=>r.recordType==='chapter'?{...r,data:{...r.data,events:r.data.events.flatMap(e=>e.eventId===link.eventId?value?[{...e,eventId:value}]:[]:[e])}}:r}));break;case'plot':field('storyId',record.data.storyId);break;case'decision-context':field('storyId',record.data.storyId);field('decisionId',record.data.decisionId);break;case'decision':field('typeId',record.data.typeId);list('characterIds',record.data.characterIds);list('eventIds',record.data.eventIds);list('followingDecisionIds',record.data.followingDecisionIds);maker();break;case'event':field('characterId',record.data.characterId,record.data.kind==='ordinary');maker();break;case'character':field('birthEventId',record.data.birthEventId);break;case'affiliation':field('characterId',record.data.characterId);field('factionId',record.data.factionId,true);break;case'view':record.data.makers.forEach(m=>{if(m.kind!=='none')refs.push({targetId:m.id,label:'visibility maker',canRemove:true,replace:(r,value)=>r.recordType==='view'?{...r,data:{...r.data,makers:r.data.makers.flatMap(x=>x.kind!=='none'&&x.id===m.id?value?[{...x,id:value}]:[]:[x])}}:r});});record.data.categories.forEach(c=>{if(c.kind==='decision-type')refs.push({targetId:c.id,label:'visibility category',canRemove:true,replace:(r,value)=>r.recordType==='view'?{...r,data:{...r.data,categories:r.data.categories.flatMap(x=>x.kind==='decision-type'&&x.id===c.id?value?[{...x,id:value}]:[]:[x])}}:r});});break;}
 return refs;
}
